import{_ as t,o as n,c as r,j as e}from"./chunks/framework.DvE3tBec.js";const u=JSON.parse('{"title":"openEO API v1.1.0 released","description":"","frontmatter":{"news":true,"title":"openEO API v1.1.0 released","date":"2021-05-17T00:00:00.000Z","author":"Matthias Mohr","aside":false},"headers":[],"relativePath":"news/2021-05-17-openeo-api-110-released.md","filePath":"news/2021-05-17-openeo-api-110-released.md","lastUpdated":1621263124000}'),o={name:"news/2021-05-17-openeo-api-110-released.md"};function s(i,a,l,d,p,c){return n(),r("div",null,[...a[0]||(a[0]=[e("p",null,"Today, we released a new version 1.1.0 of the openEO API.",-1),e("p",null,"It features a number of relatively minor, but interesting new features. The OpenID Connect authentication process has been made easier by providing negotiating client IDs automatically. Jobs, Services, and Logs can provide detailed usage metrics to users so that they can monitor memory usage, CPU usage, data transfer, and other metrics. For synchronous processing, a recommendation has been added on how to deliver multiple files (via TAR archives). Overall, we also aligned better with the STAC specification, which recently has been released in 1.0.0 release candidate state. For several parts exposed by the API can now be declared to be experimental or deprecated. Finally, the API specification also clarifies several ambiguous parts of the specification.",-1),e("p",null,"Back-ends and clients are advised to check their implementations against the new specification and update accordingly.",-1),e("p",null,"More details about the release:",-1),e("ul",null,[e("li",null,[e("a",{href:"https://github.com/Open-EO/openeo-api/tree/1.1.0/CHANGELOG.md",target:"_blank",rel:"noreferrer"},"Changelog")]),e("li",null,[e("a",{href:"https://api.openeo.org/",target:"_blank",rel:"noreferrer"},"API documentation")])],-1)])])}const m=t(o,[["render",s]]);export{u as __pageData,m as default};
